function friendlyError(e){const code=String(e.message??e).split('：')[0];return errorMessages[code]??(e.name==='TimeoutError'||e.name==='AbortError'?"连接逾时，无法确认是否已保存。请刷新并读回草稿或审核纪录，核对后再操作。":e instanceof SyntaxError?"文件内容无法读取。请选择由 Kinseed 导出的完整身份包文件，再重新导入。":/^[A-Z][A-Z0-9_:]+$/.test(code)?"数据未通过检查，这次操作没有确认成功。请核对名称、必填内容及所选身份包；高端诊断可提供给维护人员。":String(e.message??e));}
